package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.*;
import jakarta.servlet.http.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.security.core.Authentication;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class DocumentRevisionDirectoryControllerTest{
 DocumentRevisionDirectoryControllerTest()throws Exception{}
 final ApplicationSessionIdentity identities=mock(ApplicationSessionIdentity.class);final DocumentRevisionDirectoryService service=mock(DocumentRevisionDirectoryService.class);final PermissionSchema json=new PermissionSchema();final DocumentRevisionDirectoryController controller=new DocumentRevisionDirectoryController(identities,service,json);
 final ApplicationSessionIdentity.Verified subject=mock(ApplicationSessionIdentity.Verified.class);final Authentication auth=mock(Authentication.class);final HttpServletResponse response=mock(HttpServletResponse.class);
 HttpServletRequest request(Map<String,String[]> params){var r=mock(HttpServletRequest.class);when(r.getHeaders("X-Schema-Version")).thenReturn(Collections.enumeration(List.of("1.0.0")));when(r.getHeaders("X-Context-Revision")).thenReturn(Collections.enumeration(List.of("1")));when(r.getParameterMap()).thenReturn(params);for(var e:params.entrySet())when(r.getParameter(e.getKey())).thenReturn(e.getValue()[0]);when(identities.requireCurrent(r,auth)).thenReturn(subject);return r;}
 @Test void exactLimitAndCursorUseCurrentIdentityAndHeadEnvelope()throws Exception{String doc=DocumentRevisionDirectoryServiceTest.id(5),token=DocumentRevisionDirectoryServiceTest.id(90);var r=request(Map.of("limit",new String[]{"2"},"cursor",new String[]{token}));var page=json.object().put("document_head_revision","12");when(service.read(subject,"1",doc,2,token)).thenReturn(page);var result=controller.read(r,response,auth,doc);assertEquals(page,result.required("data"));assertEquals("12",result.required("resource_revision").textValue());verify(response).setHeader("X-Resource-Revision","12");verify(response).setHeader("Cache-Control","no-store");}
 @Test void missingDuplicateAndLegacyPageSizeAreRejected()throws Exception{for(var params:List.<Map<String,String[]>>of(Map.of(),Map.of("limit",new String[]{"1","2"}),Map.of("page_size",new String[]{"1"}),Map.of("limit",new String[]{"01"}))){assertThrows(SchemaRejection.class,()->controller.read(request(params),response,auth,DocumentRevisionDirectoryServiceTest.id(5)));}verifyNoInteractions(service);}
 @Test void authenticationDenialNeverCallsDirectory()throws Exception{var r=request(Map.of("limit",new String[]{"1"}));when(identities.requireCurrent(r,auth)).thenThrow(new org.springframework.security.authentication.AuthenticationCredentialsNotFoundException("no session"));assertThrows(org.springframework.security.core.AuthenticationException.class,()->controller.read(r,response,auth,DocumentRevisionDirectoryServiceTest.id(5)));verifyNoInteractions(service);}
}
